Definition P_UB_SPW_STATE : Z := 0x3c7d8.
Definition P_UB_SPW_IMPL  : Z := 0x3c83c.

Definition spw_state_null_post (ra sp gp tp s0 s1 a0 a1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (T : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(T, T + 16)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' T [C8 (wz 0); C8 (wz 0)].

Definition spw_state_null_stmt : Prop :=
  forall (T W : Z) (jt : list byte) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  rw_cells usegs m T [CB 16 jt] -> T mod 8 = 0 -> T + 16 <= 2^64 ->
  (* [comment removed for export] *)
  ro_cells usegs m (W + 8) [C8 (wz 0)] -> (T + 16 <= W + 8 \/ W + 16 <= T) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (spw_state_null_post ra sp gp tp s0 s1 (wz T) (wz W) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc T m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz T) (wz W) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_SPW_STATE) fc None m (seg_rom usegs)).
