Definition spw_impl_one_post (ra sp gp tp s0 s1 a0 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (T implb vp w i : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz (implb + 32)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(T, T + 16); (implb + 8, implb + 12)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' T [C8 (wz (implb + 32)); C8 (wz implb)]
    /\ rw_cells usegs m' implb (SpcHdrCells (mkSPC vp 2 w i) j7).

Definition spw_impl_one_stmt : Prop :=
  forall (T W implb vp w i : Z) (jt j7 : list byte) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  rw_cells usegs m T [CB 16 jt] -> T mod 8 = 0 -> T + 16 <= 2^64 ->
  (* [comment removed for export] *)
  ro_cells usegs m W [C8 (wz (implb + 32)); C8 (wz implb)] -> (T + 16 <= W \/ W + 16 <= T) ->
  (* [comment removed for export] *)
  rw_cells usegs m implb (SpcHdrCells (mkSPC vp 1 w i) j7) -> 0 < implb -> implb mod 16 = 0 -> implb + 32 <= 2^64 ->
  (T + 16 <= implb \/ implb + 32 <= T) -> (W + 16 <= implb \/ implb + 32 <= W) ->
