Definition shcount_dtor_dec2_post (ra sp gp tp s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (implb vp w i lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (implb + 8, implb + 12)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' implb (SpcHdrCells (mkSPC vp 1 w i) j7).

Definition shcount_dtor_dec2_stmt : Prop :=
  forall (PN implb vp w i lo : Z) (j7 : list byte) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells usegs m PN [C8 (wz implb)] -> (PN + 8 <= lo \/ bv_unsigned sp <= PN) ->
  rw_cells usegs m implb (SpcHdrCells (mkSPC vp 2 w i) j7) -> 0 < implb -> implb mod 16 = 0 -> implb + 32 <= hceil ->
  stk usegs m lo (bv_unsigned sp) -> lo + SHCOUNT_DTOR_SHORT_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (shcount_dtor_dec2_post ra sp gp tp s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc implb vp w i lo j7 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz PN) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SHCOUNT_DTOR) fc None m (seg_rom usegs)).

